  if (removed.size != operation.assignments.size)
    fail("SPINAL-PARAMETERIZED-VERILOG-VEC-ASSIGNMENT-LINEAGE-UNSUPPORTED",
      "field auto-connect does not cover every exact assignment once", operation.sourceLocation)
